function clubVolunteerDomainLeadForm(domainId){const p=current(),domain=clubVolunteerDomains(p).find(d=>d.id===domainId),v=clubVolunteerDomainLatest(p,domainId);if(!domain||!clubVolunteerDomainManager(p))return toast('Current event lead or assigned mentor required.');const roster=clubVolunteerDomainRoster(p,domainId);modal(`<h2>Appoint / replace domain lead</h2><p>${esc(domain.title)} · Only selected volunteers already handed into this domain and still active can be appointed. This coordinates the domain; mentor verification and wider event authority remain unchanged.</p><form onsubmit="saveClubVolunteerDomainLead(event,'${domain.id}',${v?.version||0})"><label>Domain lead<select name="student"><option value="">End current appointment</option>${roster.map(id=>`<option value="${esc(id)}" ${v?.student===id?'selected':''}>${esc(name(id))}</option>`).join('')}</select></label><label>Reason<textarea name="reason" required maxlength="1000"></textarea></label><label><input type="checkbox" name="confirm" value="yes" required> Confirm this domain appointment change.</label><button type="submit">Save appointment</button></form>`)}
function saveClubVolunteerDomainLead(event,domainId,expectedVersion){event.preventDefault();const p=current(),domain=clubVolunteerDomains(p).find(d=>d.id===domainId),v=clubVolunteerDomainLatest(p,domainId),f=Object.fromEntries(new FormData(event.target));if(!domain||!clubVolunteerDomainManager(p)||!Number.isSafeInteger(expectedVersion)||expectedVersion!==(v?.version||0)||Object.keys(f).some(k=>!['student','reason','confirm'].includes(k))||typeof f.student!=='string'||f.confirm!=='yes'||typeof f.reason!=='string'||!f.reason.trim()||f.reason.trim().length>1000||(p.clubVolunteerDomainLeads||[]).filter(r=>r.domainId===domainId).length>1)return toast('Current authority, domain, appointment revision, reason and confirmation required.');if(f.student?!clubVolunteerDomainRoster(p,domainId).includes(f.student)||v?.state==='ACTIVE'&&v.student===f.student:!v||v.state!=='ACTIVE')return toast('Choose another active selected volunteer in this domain or end an active appointment.');p.clubVolunteerDomainLeads??=[];let record=p.clubVolunteerDomainLeads.find(r=>r.domainId===domainId);if(!record){record={domainId,versions:[]};p.clubVolunteerDomainLeads.push(record)}record.versions.push({version:(v?.version||0)+1,openingVersion:p.clubVolunteerOpening.version,student:f.student||null,state:f.student?'ACTIVE':'ENDED',by:uid,at:new Date().toISOString(),reason:f.reason.trim()});log(p,'Volunteer domain lead '+(f.student?'appointed':'ended')+': '+domain.title);closeModal();render();toast('Domain appointment saved; historical records and existing task/review authority retained.')}
function clubVolunteerDomainPanel(p){if(!p?.clubVolunteerOpening&&!p?.clubVolunteerDomainSummary||!canSee(p))return '';const rows=p.clubVolunteerDomainSummary||clubVolunteerDomainSummary(p),manager=clubVolunteerDomainManager(p);if(!rows.length)return '';return `<section class="panel"><h2>Volunteer domain leads</h2><p>Domain leads coordinate selected, enrolled volunteers. Individual tasks and progress use the existing task workflow; mentor verification remains separate. Current domain leads can assign scoped responsibilities and monitor them below.</p>${rows.map(d=>`<article class="card"><h3>${esc(d.title)}</h3><p>${d.student?esc(name(d.student)):'No lead appointed'} · ${d.current?'Current appointment':d.state==='ACTIVE'?'Eligibility or source changed; appointment inactive':esc(d.state)} · v${d.version}</p>${manager?btn('Appoint / replace / end',`clubVolunteerDomainLeadForm('${d.domainId}')`):''}${clubRecruitmentPlanReader(p)?`<details><summary>Appointment history</summary>${((p.clubVolunteerDomainLeads||[]).find(r=>r.domainId===d.domainId)?.versions||[]).map(v=>`<p>v${v.version} · ${esc(v.state)} · ${v.student?esc(name(v.student)):'No lead'} · ${esc(name(v.by))} · ${esc(eventTime(v.at))} · ${esc(v.reason)}</p>`).join('')||'<p>No appointment history.</p>'}</details>`:''}</article>`).join('')}</section>`}
const clubVolunteerDomainPreviousOverview=projectOverview;projectOverview=function(p){return clubVolunteerDomainPreviousOverview(p)+clubVolunteerDomainPanel(p)};

function clubVolunteerDomainTaskAuthority(p,domainId){const v=clubVolunteerDomainLatest(p,domainId);return canSee(p)&&clubVolunteerDomainLeadCurrent(p,domainId)&&v.student===uid}
function clubVolunteerDomainTaskContext(p){return clubVolunteerDomains(p).map(d=>({domainId:d.id,title:d.title,sourceCurrent:clubVolunteerDomainSourceCurrent(p),leadVersion:clubVolunteerDomainLatest(p,d.id)?.version||0,canAssign:clubVolunteerDomainTaskAuthority(p,d.id),assignees:clubVolunteerDomainTaskAuthority(p,d.id)?clubVolunteerDomainRoster(p,d.id):[]}))}
function clubVolunteerDomainTaskContexts(p){return p.clubVolunteerDomainTaskContext||clubVolunteerDomainTaskContext(p)}
function clubVolunteerDomainTaskForm(domainId){const p=current(),c=clubVolunteerDomainTaskContexts(p).find(d=>d.domainId===domainId);if(!c?.canAssign)return toast('Current domain-lead appointment required.');modal(`<h2>Assign domain responsibility</h2><p>${esc(c.title)} · This task uses the existing individual submission and mentor-verification workflow. Organizational domains are separate from the four learning assessment domains.</p><form onsubmit="assignClubVolunteerDomainTask(event,'${c.domainId}',${c.leadVersion},${p.tasks.length})">${field('title','Task title','')}<label>Responsible volunteer<select name="assignee">${c.assignees.map(id=>`<option value="${esc(id)}">${esc(name(id))}</option>`).join('')}</select></label>${field('due','Task deadline',p.due,'date')}${[['expectedOutput','Expected deliverable'],['responsibility','Individual responsibility'],['evidenceRequirement','Required evidence'],['groupReference','Shared group work reference (optional)']].map(([key,title])=>`<label>${title}<textarea name="${key}"></textarea></label>`).join('')}<p>Select learning domains and observable criteria.</p>${Object.entries(taskDomainNames).map(([key,title])=>`<label><input type="checkbox" name="${key}" value="yes">${esc(title)}</label><label>${esc(title)} criterion<textarea name="criterion_${key}"></textarea></label>`).join('')}<label>Assignment reason<textarea name="reason" required></textarea></label><button type="submit">Assign domain task</button></form>`)}
function assignClubVolunteerDomainTask(event,domainId,expectedLeadVersion,expectedTaskCount){event.preventDefault();const p=current(),v=clubVolunteerDomainLatest(p,domainId),f=Object.fromEntries(new FormData(event.target)),allowed=['title','assignee','due','expectedOutput','responsibility','evidenceRequirement','groupReference','reason',...Object.keys(taskDomainNames).flatMap(d=>[d,'criterion_'+d])];if(!clubVolunteerDomainTaskAuthority(p,domainId)||!Number.isSafeInteger(expectedLeadVersion)||v.version!==expectedLeadVersion||!Number.isSafeInteger(expectedTaskCount)||p.tasks.length!==expectedTaskCount||Object.keys(f).some(k=>!allowed.includes(k))||!clubVolunteerDomainRoster(p,domainId).includes(f.assignee))return toast('Refresh this domain assignment: current appointment, roster and task revision are required.');const a=clubVolunteerOwn(p,f.assignee),domain=clubVolunteerDomains(p).find(d=>d.id===domainId),task=recordAuthorizedTaskMapping(event,-1,true);if(!task)return;task.clubVolunteerDomain={domainId,title:domain.title,openingVersion:p.clubVolunteerOpening.version,leadVersion:v.version,lead:uid,applicationId:a.id,applicationRevision:a.revision};save();render();toast('Domain task assigned. Student progress and mentor verification use the existing workflow.')}
function clubVolunteerDomainTaskPanel(p){if(!p?.sourceClub||!canSee(p))return '';const contexts=clubVolunteerDomainTaskContexts(p);if(!contexts.length)return '';return `<section class="panel"><h2>Domain task assignment & monitoring</h2><p>Assignment and progress are distinct from verified completion. Done means current mentor verification. Submission details, feedback and scores retain existing privacy controls. Existing unlinked tasks remain in the task board; no domain is inferred.</p>${contexts.map(c=>{const rows=p.tasks.map((t,i)=>({t,i})).filter(({t})=>t.clubVolunteerDomain?.domainId===c.domainId);return `<article class="card"><h3>${esc(c.title)}</h3>${!c.sourceCurrent?'<p>Source or event is inactive. Task records below are retained for review.</p>':''}${c.canAssign?btn('Assign domain task',`clubVolunteerDomainTaskForm('${c.domainId}')`):''}${tableHTML(['Task','Responsible student','Due','Progress','Blocker','Attention'],rows.map(({t})=>[esc(t.title),esc(name(t.assignee)),esc(t.due),esc(label(taskBoardStage(p,t))),t.execution?.blocked?esc(t.execution.blockerReason||'Blocked'):'None recorded',t.due<localDay()&&!taskAssessmentCurrent(p,t)?'Overdue':'—']))}${!rows.length?'<p>No linked domain tasks.</p>':''}</article>`}).join('')}${btn('Open existing task workflow',"tab='Tasks';render()")}</section>`}
const clubVolunteerDomainTaskPreviousOverview=projectOverview;projectOverview=function(p){return clubVolunteerDomainTaskPreviousOverview(p)+clubVolunteerDomainTaskPanel(p)};

function clubVolunteerDashboardActions(){const rows=[];for(const p of db.projects){if(!p.sourceClub||!canSee(p)||participantResolution(p,uid))continue;const add=(kind,title,version)=>rows.push({key:'club-volunteer-dashboard:'+p.id+':'+kind,title,route:'Projects',sourceId:p.id,version,recipient:uid,due:p.due||null,kind:'RESPONSIBILITY'});if(clubVolunteerReviewWriter(p)){const pending=(p.clubVolunteerApplications||[]).filter(a=>a.openingVersion===p.clubVolunteerOpening.version&&a.state==='APPLIED'&&clubVolunteerOwn(p,a.student)===a&&clubVolunteerReviewWriter(p,a));if(pending.length)add('review','Review '+pending.length+' club volunteer application'+(pending.length===1?'':'s'),p.clubVolunteerOpening.version);const preview=clubVolunteerHandoffPreview(p);if(preview.rows.length)add('handoff',preview.errors.length?'Review selected-volunteer handoff prerequisites':'Confirm roster handoff for '+preview.rows.length+' selected volunteer'+(preview.rows.length===1?'':'s'),p.clubVolunteerOpening.version)}for(const c of clubVolunteerDomainTaskContexts(p)){const summary=(p.clubVolunteerDomainSummary||clubVolunteerDomainSummary(p)).find(d=>d.domainId===c.domainId);if(c.canAssign&&c.sourceCurrent&&summary?.current&&summary.student===uid&&summary.version===c.leadVersion){const count=p.tasks.filter(t=>t.clubVolunteerDomain?.domainId===c.domainId).length;add('domain:'+c.domainId,'Coordinate '+c.title+' domain · '+count+' linked task'+(count===1?'':'s'),c.leadVersion)}}}return rows}
const clubVolunteerPreviousDashboardAssignedActions=dashboardAssignedActions;dashboardAssignedActions=function(){const rows=[...clubVolunteerPreviousDashboardAssignedActions(),...clubVolunteerDashboardActions()];return [...new Map(rows.map(a=>[JSON.stringify([a.route,a.sourceId,a.key,a.version]),a])).values()]};
const clubVolunteerPreviousDashboardSnapshot=dashboardSnapshot;dashboardSnapshot=function(){const snapshot=clubVolunteerPreviousDashboardSnapshot();if(intakeStudent())snapshot.verified=snapshot.verified.filter(p=>activityControlActive(p)&&deliveryIndividualReady(p,uid));return snapshot};
function clubVolunteerDashboardPanel(){const rows=clubVolunteerDashboardActions();if(!rows.length)return '';return `<section class="panel"><h2>Your club event responsibilities</h2><p>Current organizer reviews, handoff follow-ups and domain coordination are derived from your existing assignments. These are workflow responsibilities, not new approval grants or broadcast notices.</p>${rows.map(a=>`<article class="card"><h3>${esc(a.title)}</h3><p>${esc(db.projects.find(p=>p.id===a.sourceId)?.title||a.sourceId)} · ${esc(a.sourceId)}</p>${btn('Open Projects overview',"go('Projects')")}${btn('Open assigned action queue',"go('Action Centre')")}</article>`).join('')}</section>`}
const clubVolunteerPreviousRoleDashboardOverview=roleDashboardOverview;roleDashboardOverview=function(){return clubVolunteerPreviousRoleDashboardOverview()+clubVolunteerDashboardPanel()};
